# =============================================================================
# AlphaCP — D11 RESTART SERVICES v1.0  (live panel 0.75.x + paneld · 09 Oct 2026)
#
# Phase-2 Wave D11: WHM "Restart Services" — PEHLI agent-touching wave.
#   AGENT: service.restart task (11 allowlisted services, paneld EXCLUDED)
#          + ServiceRestart handler (dobara validate, state re-check)
#   PANEL: Service Status page par per-service Restart buttons + audit
# 5 files. paneld restart gate: pehle active tha + restart fail => ROLLBACK.
# DB me KOI change nahi.
# Safety: har purani file backup (.bak-d11restart-<stamp>) -> install ->
#   view:clear + route:clear + php-fpm reload -> health -> AUTO-ROLLBACK.
# =============================================================================
set -Eeuo pipefail

D11_VERSION="1.0"
PANEL_ROOT="${PANEL_ROOT:-/usr/local/alphacp/panel}"
STAMP="$(date -u +%Y%m%d%H%M%S)"
LOG_FILE="/var/log/alphacp-d11-restart-services.log"

C_B=$'\033[1m'; C_G=$'\033[32m'; C_R=$'\033[31m'; C_Y=$'\033[33m'; C_0=$'\033[0m'
say() { printf '%s\n' "$*"; }
log() { printf '%s [%s]\n' "$(date -u '+%F %T')Z" "$*" >>"${LOG_FILE}" 2>/dev/null || true; }
ok()  { log "OK   $*"; say "${C_G}[OK]${C_0} $*"; }
warn(){ log "WARN $*"; say "${C_Y}[!]${C_0} $*"; }
die() { log "FAIL $*"; say "${C_R}[x]${C_0} $*"; say "Log: ${LOG_FILE}"; exit 1; }

say ""
say "${C_B}== AlphaCP D11 RESTART SERVICES v${D11_VERSION} ==${C_0}"
[[ "${EUID}" -eq 0 ]] || die "root chahiye: sudo bash $0"
[[ -d "${PANEL_ROOT}/public/assets" ]] || die "panel nahi mila: ${PANEL_ROOT}"
[[ -f "${PANEL_ROOT}/public/assets/panel.js" ]] || die "pehle theme-fix v1.2 install karo (panel.js missing) — COMMANDS.md dekho"

